(() => {
  'use strict';
  const {drugs,categories}=MED_DATA, L=MED_LOGIC;
  const $=s=>document.querySelector(s), KEY='care-medicine-52-v2';
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let storageIssue='', saved={};
  try {saved=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('care-medicine-52-v1')||'{}');if(!saved||typeof saved!=='object')saved={};}catch{storageIssue='保存された記録を読み込めません。この画面を閉じる前にブラウザの保存設定を確認してください。';}
  saved.progress=L.migrateProgress(saved.progress,saved.version||1);
  const prefs={sound:false,volume:35,dark:matchMedia('(prefers-color-scheme: dark)').matches,name:'brand',...saved.prefs};
  const progress={};
  for(const d of drugs){const p=saved.progress?.[d.id];if(p&&Number.isFinite(p.attempts)&&p.attempts>=0)progress[d.id]={...L.fresh(),...p,skills:{...L.fresh().skills,...p.skills}};}
  let session=null, audio=null, listQuery='', listCategory='', workplaceOnly=false, photoOnly=false, observation='', setupCategory='', setupMode='category', setupDifficulty=2;
  const names={category:'分類を覚える',action:'作用を覚える',care:'観察ポイント',report:'看護師へ報告する',photo:'写真で目的を学ぶ',recall:'振り返りカード'};
  const levels=['未学習','見たことがある','分類がわかる','作用がわかる','観察までわかる','学習達成'];
  const displayName=d=>prefs.name==='brand'&&d.brandNames.length?d.brandNames[0]:d.learningName;
  const safety='このアプリは介護職員の学習を目的としたものです。薬の投与、中止、増減などを自己判断するためのものではありません。利用者の異常や体調変化を認めた場合は、看護師・医師などへ報告してください。';
  function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:2,prefs,progress}));}catch{storageIssue='記録を保存できません。ブラウザの保存制限や空き容量を確認してください。この画面内では学習を続けられます。';}showStorage();}
  function showStorage(){const e=$('#storage-warning');e.hidden=!storageIssue;e.textContent=storageIssue;}
  function applyPrefs(){document.body.classList.toggle('dark',prefs.dark);$('#sound-toggle').textContent=prefs.sound?'♫':'♪';$('#sound-toggle').setAttribute('aria-pressed',String(prefs.sound));$('#sound-toggle').setAttribute('aria-label',prefs.sound?'効果音をオフにする':'効果音をオンにする');$('#sound-toggle').title=prefs.sound?'効果音：オン':'効果音：オフ';$('#sound-setting').checked=prefs.sound;$('#dark-setting').checked=prefs.dark;$('#volume').value=prefs.volume;$('#name-setting').value=prefs.name;}
  function unlock(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(Audio&&!audio)audio=new Audio();if(audio?.state==='suspended')audio.resume().catch(()=>{});}catch{}}
  function tone(type){if(!prefs.sound||!prefs.volume)return;unlock();if(!audio)return;const notes=type==='wrong'?[220,174]:type==='done'?[523,659,784,1046]:[659,880];try{notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.13;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.12*prefs.volume/100,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.18);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.2);o.onended=()=>{o.disconnect();g.disconnect();};});}catch{}}
  function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
  function mastery(){const mastered=drugs.filter(d=>progress[d.id]?.level===5).length, learning=drugs.filter(d=>progress[d.id]?.attempts&&progress[d.id].level<5).length;return{mastered,learning,unseen:52-mastered-learning};}
  function bar(m){return `<div class="progress" aria-label="習得 ${m.mastered}、学習中 ${m.learning}、未学習 ${m.unseen}"><span style="width:${m.mastered/52*100}%"></span><span class="learning" style="width:${m.learning/52*100}%"></span></div><div class="legend"><span>習得 ${m.mastered}</span><span>学習中 ${m.learning}</span><span>未学習 ${m.unseen}</span></div>`;}
  function home(){const plan=L.today(drugs,progress),m=mastery();return `<div class="eyebrow">毎日の学び</div><h1>気づく・観察する・報告する</h1><p class="intro">何の薬かを知り、普段との違いを看護師へ。</p><div class="role-note">薬の投与・中止・変更を自己判断しない。最終判断は看護師・医師・薬剤師等へ。</div><section class="workplace-panel"><div class="section-heading"><h2>★ 現場で使う4つの薬</h2><button class="back" data-do="workplace">一覧へ ›</button></div><div class="workplace-grid">${drugs.filter(d=>d.isWorkplaceDrug).map(d=>`<a href="#drug/${d.id}"><strong>${esc(d.id===22?"カロナール":d.learningName)}</strong><small>${esc(d.purpose)}</small></a>`).join("")}</div></section><div class="dashboard"><div><section><div class="metrics"><div class="metric"><span>新しく覚える</span><strong>${plan.unseen.length}</strong></div><div class="metric"><span>復習</span><strong>${plan.due.length}</strong></div><div class="metric"><span>苦手</span><strong>${plan.difficult.length}</strong></div></div><button class="primary wide" data-do="today">${plan.all.length?plan.all.length+'項目を学ぶ':'追加で5項目を復習'}</button></section><section><div class="section-heading"><h2>習得状況</h2><strong>${m.mastered} / 52</strong></div>${bar(m)}</section><section><h2>重点学習</h2><button class="secondary wide" data-do="important">重要薬の観察ポイント</button></section></div><div><section><h2>学習モード</h2><p class="photo-summary">実物写真つき：${drugs.filter(d=>L.approvedImages(d).length).length} / 52薬 <button class="secondary" data-do="photos">写真カードを見る</button></p>${Object.entries(names).map(([k,n],i)=>`<button class="mode-row" data-mode="${k}"><span><b class="step">${String(i+1).padStart(2,'0')}</b>${n}</span><small>${k==='recall'?'○ △ ×':'クイズ'}</small></button>`).join('')}</section></div></div><section><div class="section-heading"><h2>分類から学ぶ</h2><span class="muted">15分類</span></div><div class="category-grid">${categories.map((c,i)=>`<button data-category="${i}">${c}<small>${drugs.filter(d=>d.category===c).length}項目</small></button>`).join('')}</div></section>`;}
  function setup(){if(setupMode==='photo'&&!drugs.some(d=>L.approvedImages(d).length))return `<div class="study"><button class="back" data-do="home">‹ ホーム</button><h1>写真クイズ</h1><div class="photo-empty">使用許可と製品一致を確認できた写真がまだありません。</div><p>写真クイズは現在0問です。確認できた写真だけを出題対象にします。</p><p class="photo-warning">${esc(MED_DATA.photoWarning)}</p><button class="primary wide" data-mode="report">報告の練習へ</button><a href="#sources">52薬の調査結果を見る</a></div>`;return `<div class="study"><button class="back" data-do="home">‹ ホーム</button><h1>${names[setupMode]}</h1><div class="filters"><label>分類<select id="study-category"><option value="">すべての分類</option>${categories.map(c=>`<option ${setupCategory===c?'selected':''}>${c}</option>`).join('')}</select></label><label>学習量<select id="study-count"><option value="5">5項目</option><option value="10">10項目</option></select></label></div>${!['recall','photo'].includes(setupMode)?`<label>難易度<select id="difficulty"><option value="2" ${setupDifficulty===2?'selected':''}>レベル1：2択</option><option value="4" ${setupDifficulty===4?'selected':''}>レベル2：4択</option><option value="hint" ${setupDifficulty==='hint'?'selected':''}>レベル3：ヒントで思い出す</option></select></label>`:'<p class="muted">選んだモードで目的・観察を学びます。写真は収録済みの薬だけを出題し、外観だけで薬を断定しません。</p>'}<button class="primary wide" style="margin-top:24px" data-do="begin">学習を始める</button></div>`;}
  function start(items,mode='category',difficulty=2){if(!items.length){go('setup');return;}unlock();session={queue:items.map(d=>({id:d.id,mode})),index:0,results:[],options:null,answered:false,revealed:false,hint:false,retried:new Set(),difficulty,finished:false};go('study');}
  function current(){return session?.queue[session.index];}
  function study(){if(!session)return setup();if(session.finished)return finish();const item=current(),d=drugs.find(x=>x.id===item.id);const recall=item.mode==='recall',hintMode=session.difficulty==='hint';if(!recall&&!hintMode&&!session.options)session.options=L.choices(d,item.mode,drugs,Number(session.difficulty));return `<div class="study"><div class="session-actions"><button class="back" data-do="quit">‹ 学習を終了</button><small>${session.index+1} / ${session.queue.length}問</small></div><div class="eyebrow">${names[item.mode]}${item.retry?' ・ もう一度':''}</div><div class="progress"><span style="width:${session.index/session.queue.length*100}%"></span></div><h1>${esc(item.mode==='photo'?'この代表製品の目的は？':displayName(d))}</h1>${item.mode==='photo'?photoPanel(d,!session.answered):''}<div class="section-heading"><span class="muted">${item.mode==='photo'?'':displayName(d)!==d.genericName?'一般名：'+esc(d.genericName):d.brandNames.length?'商品名：'+esc(d.brandNames.join('／')):''}</span><button class="read-button" ${item.mode==='photo'&&!session.answered?'hidden':''} data-read="${d.id}">読み上げ</button></div>${recall||hintMode?recallUI(d,item.mode):quizUI(d,item.mode)}</div>`;}
  function quizUI(d,mode){const correct=L.answer(d,mode);const question=mode==='report'?'看護師に伝える報告として適切なのは？':mode==='photo'?'写真は見覚えをつくる補助です。この代表製品は何の薬？':mode==='category'?'どの分類の薬でしょう？':mode==='action'?'何の薬でしょう？':'この教材で結びつける観察ポイントは？';return `<p class="question">${question}</p><div class="answers">${session.options.map((o,i)=>`<button class="answer ${session.answered?(o===correct?'correct':session.selected===i?'wrong':''):''}" data-answer="${i}" ${session.answered?'disabled':''}><span class="choice-letter">${session.answered&&o===correct?'✓':String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}</div>${session.answered?`<div class="feedback ${session.correct?'':'wrong'}" role="status"><h2>${session.correct?'正解':'もう一度、覚えよう'}</h2><p><strong>${esc(correct)}</strong></p><p>${esc(d.note)}</p>${mode==='report'?`<p>${esc(d.reportNote)}</p>`:reportBlock(d)}${mode==='photo'?facts(d):''}${mode==='care'?'<small>ここにない症状も観察・報告の対象です。</small>':''}</div><button class="primary wide" data-do="next">${session.index+1===session.queue.length?'結果を見る':'次の問題へ'}</button>`:''}`;}
  function reportBlock(d){return '<section class="report-block"><h2>看護師への報告例</h2><blockquote>'+esc(d.reportExample)+'</blockquote><p class="muted">'+esc(d.reportNote)+'</p></section>';}
  function facts(d){return '<dl class="detail-rows"><div class="purpose"><dt>何の薬？</dt><dd>'+esc(d.purpose)+'</dd></div><div><dt>観察するところ</dt><dd class="care-tags">'+d.carePoints.map(p=>'<span>'+esc(p)+'</span>').join('')+'</dd></div><div><dt>分類</dt><dd>'+esc(d.subCategory)+'</dd></div></dl>';}
  function officialLink(url,label){return typeof url==='string'&&/^https:\/\//.test(url)?'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+' ↗</a>':'';}
  function photoPanel(d,hideIdentity=false){
    const images=L.approvedImages(d);
    return '<section class="photo-panel"><h2>実物の手掛かり</h2>'+(images.length?images.map(i=>'<figure><a href="'+esc(i.path)+'" target="_blank" rel="noopener" aria-label="写真を大きく表示"><img class="drug-photo" src="'+esc(i.path)+'" alt="'+esc(i.productName+' '+i.view)+'"></a><figcaption>'+esc(i.view)+'<br><strong>'+esc(i.appearanceNote)+'</strong><br>'+esc(i.author)+' / '+officialLink(i.sourceUrl,'出典')+' / '+officialLink(i.licenseUrl,i.license)+'<br>'+esc(i.changes)+'</figcaption></figure>').join(''):'<div class="photo-empty">写真なし<br><small>転載許可と製品一致を確認できた写真は未登録です。</small></div>')+'<p class="photo-warning">'+esc(d.photoWarning)+'</p><p><strong>代表製品：'+esc(d.representativeProduct)+'</strong><br>規格：'+esc(d.strength)+'<br>'+esc(d.currentManufacturer?'写真当時の製造販売元：':'製造販売元：')+esc(d.manufacturer)+(d.currentManufacturer?'<br>現在の製造販売元等：'+esc(d.currentManufacturer):'')+'</p>'+(hideIdentity?'<p class="muted">写真には製品名が含まれます。薬名の断定ではなく、表示と目的を結びつける練習です。</p>':'<p class="muted">'+esc(d.saleStatus||'販売・供給状況は未確認')+'</p>'+d.imageSources.map(x=>officialLink(x.sourceUrl,x.sourceName||'出典')).join(' / '))+'</section>';
  }
  function sourcesPage(){return '<h1>52薬の公式情報・写真調査</h1><p>製品調査：2026年10月13日／収録写真の確認：2026年10月23日。公式掲載は転載許可や継続販売の保証ではありません。確認できない項目は未確認として残しています。</p><p>収録写真：'+drugs.filter(d=>L.approvedImages(d).length).length+' / 52薬</p>'+drugs.map(d=>'<section class="source-card"><h2><a href="#drug/'+d.id+'">'+d.id+'. '+esc(d.learningName)+'</a></h2><p>'+esc(d.representativeProduct)+' ／ '+esc(d.strength)+'<br>'+esc(d.manufacturer)+(d.currentManufacturer?'<br>現在：'+esc(d.currentManufacturer):'')+'</p><p>'+esc(d.clinicalVerification)+'</p><p>'+esc(d.researchNotes||'')+'</p><p>'+esc(d.saleStatus||'販売状況未確認')+'</p>'+d.imageSources.map(x=>'<p>'+officialLink(x.sourceUrl,x.sourceName||'公式情報')+' '+officialLink(x.termsUrl,'利用条件')+'</p><p class="muted">写真：'+esc(x.imageUsageStatus||'未確認')+' ／ '+esc(x.checkedDate||'未確認')+'</p>').join('')+'</section>').join('');}
  function recallUI(d,mode){return `${session.revealed?`${facts(d)}${reportBlock(d)}<p class="muted">${esc(d.note)}</p><h2>どのくらい覚えた？</h2><div class="ratings"><button data-rating="2"><b>○</b>覚えた</button><button data-rating="1"><b>△</b>あやしい</button><button data-rating="0"><b>×</b>わからない</button></div>`:`<div class="recall-hidden"><p class="muted">${mode==='recall'?'分類・作用・観察ポイントを思い出す':names[mode]+'：答えを思い出す'}</p></div>${session.difficulty==='hint'?`<button class="secondary wide" data-do="hint">${session.hint?esc(L.answer(d,mode).slice(0,3))+'…':'ヒントを見る'}</button>`:''}<button class="primary wide" style="margin-top:12px" data-do="reveal">答えを見る</button>`}`;}
  function record(rating){const item=current();progress[item.id]=L.update(progress[item.id],item.mode,rating);session.results.push({id:item.id,rating,retry:!!item.retry});if(rating<2&&!session.retried.has(item.id)){session.retried.add(item.id);const retry={...item,retry:true};session.queue.splice(Math.min(session.index+4,session.queue.length),0,retry);if(session.index+4<session.queue.length-1)session.queue.push({...retry});}persist();tone(rating===2?'correct':'wrong');}
  function next(){session.index++;session.options=null;session.answered=false;session.revealed=false;session.hint=false;if(session.index>=session.queue.length){session.finished=true;tone('done');}render();}
  function finish(){const first=session.results.filter(r=>!r.retry),correct=first.filter(r=>r.rating===2).length;return `<div class="study"><div class="eyebrow">学習完了</div><h1>おつかれさまでした</h1><div class="score">${correct}<span class="muted" style="font-size:24px"> / ${first.length}</span></div><p>最初の回答で正解・「覚えた」になった項目</p><p class="muted">復習を含めて ${session.results.length} 回取り組みました。</p><ul class="finish-list">${first.map(r=>{const d=drugs.find(d=>d.id===r.id);return `<li><a href="#drug/${d.id}"><span>${esc(displayName(d))}</span><span class="result-label">${['× 復習','△ あやしい','○ 覚えた'][r.rating]}</span></a></li>`;}).join('')}</ul><button class="primary wide" data-do="home">ホームへ</button></div>`;}
  function normalized(s){return s.normalize('NFKC').toLowerCase().replace(/[ぁ-ゖ]/g,c=>String.fromCharCode(c.charCodeAt(0)+0x60));}
  function filtered(weakOnly){const q=normalized(listQuery);return drugs.filter(d=>(!weakOnly||L.weak(progress[d.id]))&&(!workplaceOnly||d.isWorkplaceDrug)&&(!photoOnly||L.approvedImages(d).length)&&(!listCategory||d.category===listCategory)&&(!observation||d.carePoints.some(p=>p.includes(observation)))&&(!q||normalized([d.genericName,d.learningName,d.representativeProduct,...d.brandNames,d.category,d.subCategory,d.shortAction,...d.carePoints].join(' ')).includes(q))).sort((a,b)=>Number(b.isWorkplaceDrug)-Number(a.isWorkplaceDrug)||a.id-b.id);}
  function drugRows(items){return items.length?items.map(d=>`<a href="#drug/${d.id}" class="drug-row"><span><strong>${L.approvedImages(d).length?'<span class="photo-badge">写真あり</span>':''}${d.isWorkplaceDrug?'<span class="workplace-badge">★現場使用</span>':''}${esc(displayName(d))}</strong><small>${esc(displayName(d)!==d.genericName?d.genericName:d.brandNames.join('／'))}</small><small class="list-purpose">${esc(d.purpose)}</small></span><span class="badge">${levels[progress[d.id]?.level||0]}</span></a>`).join(''):'<div class="empty"><h2>該当する薬はありません</h2><p class="muted">検索語や絞り込みを変えてみてください。</p></div>';}
  function list(weakOnly=false){const items=filtered(weakOnly),allWeak=drugs.filter(d=>L.weak(progress[d.id]));return `<div class="eyebrow">${weakOnly?'繰り返して定着':'薬名と観察をつなぐ'}</div><h1>${weakOnly?'苦手な薬':'52薬の学習カード'}</h1><button class="secondary photo-filter" data-do="toggle-photos" aria-pressed="${photoOnly}">${photoOnly?'✓ 写真ありのみ':'写真ありで絞り込む'}</button><button class="secondary workplace-filter" data-do="toggle-workplace" aria-pressed="${workplaceOnly}">${workplaceOnly?'✓ ★現場使用のみ':'★現場使用で絞り込む'}</button>${weakOnly&&!allWeak.length?'<div class="empty"><h2>苦手な薬はまだありません</h2><p class="muted">学習の回答に応じて、ここに集まります。</p><button class="primary" data-do="today">今日の学習へ</button></div>':`${weakOnly?'<button class="primary wide" data-do="weak-start">苦手を5項目復習する</button>':''}<label class="sr-only" for="search">薬名・商品名・分類・観察で検索</label><input id="search" type="search" placeholder="薬名・商品名・分類・観察で検索" value="${esc(listQuery)}"><div class="filters"><label>分類<select id="list-category"><option value="">すべて</option>${categories.map(c=>`<option ${c===listCategory?'selected':''}>${c}</option>`).join('')}</select></label><label>観察ポイント<select id="observation"><option value="">すべて</option>${['出血','低血糖','転倒','脱水','下痢','眠気','傾眠'].map(c=>`<option ${c===observation?'selected':''}>${c}</option>`).join('')}</select></label></div><p class="muted" id="result-count">${items.length}項目</p><div class="drug-list" id="drug-results">${drugRows(items)}</div>`}`;}
  function detail(id){const d=drugs.find(d=>d.id===id);if(!d)return '<h1>薬が見つかりません</h1><a href="#list">薬一覧へ</a>';const p=progress[id];return `<div class="study"><button class="back" data-do="list">‹ 薬一覧</button><div class="eyebrow">${d.category} ${d.isWorkplaceDrug?'・ ★現場使用':''}</div><h1>${esc(d.learningName)}</h1>${d.brandNames.length?`<p class="muted">商品名：${esc(d.brandNames.join('／'))}</p>`:''}<button class="read-button" data-read="${id}">読み上げ</button>${facts(d)}${reportBlock(d)}<h2>個別指示を確認すること</h2><p>${esc(d.note)}</p>${photoPanel(d)}<details><summary>公式情報と確認状況</summary><p>${esc(d.clinicalVerification)}</p><p>${esc(d.researchNotes||'')}</p>${d.imageSources.map(x=>officialLink(x.sourceUrl,x.sourceName||'公式資料')).join(' / ')}<p><a href="#sources">全52薬の調査記録</a></p></details><div class="stats-row"><span class="badge">${levels[p?.level||0]}</span><p class="muted">${p?.next?'次回復習：'+new Date(p.next).toLocaleDateString('ja-JP'):'まだ学習していません'}</p></div><div class="inline-actions"><button class="primary" data-single="${id}">暗記カードで学ぶ</button><a href="https://www.pmda.go.jp/PmdaSearch/iyakuSearch/" target="_blank" rel="noopener noreferrer">PMDAで添付文書を確認</a></div></div>`;}
  function stats(){const m=mastery(),ps=Object.values(progress),total=ps.reduce((a,p)=>a+p.attempts,0),right=ps.reduce((a,p)=>a+p.correct,0);return `<div class="eyebrow">積み重ねの記録</div><h1>学習記録</h1><div class="metrics"><div class="metric"><span>回答回数</span><strong>${total}</strong></div><div class="metric"><span>正解・覚えた</span><strong>${right}</strong></div><div class="metric"><span>習得率</span><strong>${Math.round(m.mastered/52*100)}<small>%</small></strong></div></div>${bar(m)}<p class="muted">「振り返りカード」で「覚えた」を2回記録すると学習達成になります。臨床能力や薬の識別能力を保証するものではありません。選択問題と自己評価を含む記録です。</p><h2>分類ごとの習得</h2>${categories.map(c=>{const all=drugs.filter(d=>d.category===c),done=all.filter(d=>progress[d.id]?.level===5).length;return `<div class="stats-row"><div><span>${c}</span><strong>${done} / ${all.length}</strong></div><div class="progress"><span style="width:${done/all.length*100}%"></span></div></div>`;}).join('')}`;}
  function safetyPage(){return `<div class="safety-copy"><h1>学習目的・医療安全</h1><p>${safety}</p><h2>教材について</h2><p>指定された52項目を15分類で収録しています。「インスリン」「レボドパ配合剤」など、単一の製品ではない項目も含みます。</p><p>作用・観察ポイントは初学者向けの要約です。すべての効能や副作用を網羅せず、薬・剤形・併用薬・利用者の状態によって異なります。観察問題の他の選択肢にある症状も、報告が不要という意味ではありません。</p><p>教材は専門職による全項目の監修を受けていません。施設での正式な研修利用前には、看護師・薬剤師などによる確認を受けてください。</p><h2>参照情報</h2><p>公式資料の確認範囲・未確認事項は薬ごとに記録しています。<a href="#sources">52薬の出典・利用条件・調査結果</a>をご覧ください。写真は使用許諾と製品の一致を確認できた場合だけ表示します。</p><ul><li><a href="https://www.pmda.go.jp/PmdaSearch/iyakuSearch/" target="_blank" rel="noopener noreferrer">PMDA 医療用医薬品 添付文書等情報検索</a></li><li><a href="https://www.info.pmda.go.jp/downfiles/ph/GUI/670605_3339004F1029_1_00G.pdf" target="_blank" rel="noopener noreferrer">エリキュース：患者向医薬品ガイド</a></li><li><a href="https://www.pmda.go.jp/files/000214495.pdf" target="_blank" rel="noopener noreferrer">酸化マグネシウム：適正使用に関するお願い</a></li></ul><p class="muted">作成日：2026年10月13日</p><h2>記録と音</h2><p>記録はこの端末のこのブラウザに保存されます。閲覧データの削除やプライベートブラウズの終了で消えることがあります。患者名などの個人情報は入力しません。</p><p>効果音は設定から切り替えられます。読み上げの声と対応状況は端末によって異なります。</p></div>`;}
  function render(){const path=location.hash.slice(1)||'home',page=path.split('/')[0];document.body.classList.toggle('studying',page==='study'&&!!session&&!session.finished);if(page!=='study')window.speechSynthesis?.cancel();const routes={home,setup,study,list:()=>list(false),weak:()=>list(true),stats,safety:safetyPage,sources:sourcesPage,drug:()=>detail(Number(path.split('/')[1]))};$('#main').innerHTML=(routes[page]||home)();document.querySelectorAll('.bottom-nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===(page==='drug'?'list':page)));document.title=(page==='study'?'学習中':page==='list'?'薬一覧':page==='stats'?'学習記録':'薬52種')+' | 介護士の学習ノート';window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
  function showSetup(mode,cat=''){setupMode=mode;setupCategory=cat;go('setup');}
  function speak(id){const d=drugs.find(d=>d.id===id);if(!window.speechSynthesis){alert('このブラウザでは読み上げを利用できません。');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(displayName(d));u.lang='ja-JP';u.rate=.85;u.volume=prefs.volume/100;speechSynthesis.speak(u);}
  document.addEventListener('click',e=>{
    const b=e.target.closest('button');if(!b)return;
    if(b.dataset.mode){showSetup(b.dataset.mode);return;}
    if(b.dataset.category!==undefined){showSetup('category',categories[Number(b.dataset.category)]);return;}
    if(b.dataset.single){start([drugs.find(d=>d.id===Number(b.dataset.single))],'recall');return;}
    if(b.dataset.read){speak(Number(b.dataset.read));return;}
    if(b.dataset.answer!==undefined&&session&&!session.answered){const i=Number(b.dataset.answer),d=drugs.find(d=>d.id===current().id);session.selected=i;session.correct=session.options[i]===L.answer(d,current().mode);session.answered=true;record(session.correct?2:0);render();return;}
    if(b.dataset.rating!==undefined&&session&&session.revealed&&!session.answered){session.answered=true;record(Number(b.dataset.rating));next();return;}
    switch(b.dataset.do){
      case 'home':session=null;go('home');break;
      case 'list':go('list');break;
      case 'photos':photoOnly=true;workplaceOnly=false;listCategory='';listQuery='';observation='';go('list');break;
      case 'toggle-photos':photoOnly=!photoOnly;render();break;
      case 'workplace':photoOnly=false;workplaceOnly=true;listCategory='';listQuery='';observation='';go('list');break;
      case 'toggle-workplace':workplaceOnly=!workplaceOnly;render();break;
      case 'today':{const plan=L.today(drugs,progress);const items=plan.all.length?plan.all:L.shuffle(drugs).slice(0,5);start(items);session.queue=session.queue.map(item=>{const p=progress[item.id];return {...item,mode:!p?.skills.category?'category':!p.skills.action?'action':!p.skills.care?'care':'recall'};});render();break;}
      case 'important':start(L.shuffle(drugs.filter(d=>d.importance===5)).slice(0,10),'care',4);break;
      case 'weak-start':start(L.shuffle(drugs.filter(d=>L.weak(progress[d.id]))).slice(0,5),'recall');break;
      case 'begin':{setupCategory=$('#study-category').value;setupDifficulty=setupMode==='photo'?4:$('#difficulty')?.value==='hint'?'hint':Number($('#difficulty')?.value||2);const items=L.shuffle(drugs.filter(d=>(!setupCategory||d.category===setupCategory)&&(setupMode!=='photo'||L.approvedImages(d).length))).slice(0,Number($('#study-count').value));if(!items.length){alert('この分類には出題できる写真がありません。別の分類を選んでください。');break;}start(items,setupMode,setupDifficulty);break;}
      case 'reveal':session.revealed=true;render();break;
      case 'hint':session.hint=true;render();break;
      case 'next':if(session?.answered)next();break;
      case 'quit':if(confirm('ここまでの回答は保存されています。学習を終了しますか？')){session=null;go('home');}break;
    }
  });
  document.addEventListener('input',e=>{if(e.target.id==='search'){listQuery=e.target.value;refreshResults();}});
  function refreshResults(){const items=filtered(location.hash==='#weak');$('#drug-results').innerHTML=drugRows(items);$('#result-count').textContent=items.length+'項目';}
  document.addEventListener('change',e=>{if(e.target.id==='list-category'){listCategory=e.target.value;refreshResults();}if(e.target.id==='observation'){observation=e.target.value;refreshResults();}});
  $('#settings-button').onclick=()=>{applyPrefs();$('#settings').showModal();};
  $('#sound-toggle').onclick=()=>{prefs.sound=!prefs.sound;applyPrefs();persist();tone('correct');};
  $('#sound-setting').onchange=e=>{prefs.sound=e.target.checked;applyPrefs();persist();tone('correct');};
  $('#dark-setting').onchange=e=>{prefs.dark=e.target.checked;applyPrefs();persist();};
  $('#volume').oninput=e=>{prefs.volume=Number(e.target.value);persist();};
  $('#name-setting').onchange=e=>{prefs.name=e.target.value;persist();render();};
  $('#test-sound').onclick=()=>{prefs.sound=true;applyPrefs();persist();tone('correct');};
  $('#export-data').onclick=()=>{const payload={format:'care-medicine-52',version:2,exportedAt:new Date().toISOString(),prefs,progress};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='薬52種-学習データ.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
  $('#import-data').onclick=()=>$('#import-file').click();
  $('#import-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const incoming=JSON.parse(await file.text());if(incoming.format!=='care-medicine-52'||![1,2].includes(incoming.version)||!incoming.progress)throw new Error('形式が違います');const imported=L.migrateProgress(incoming.progress,incoming.version);for(const d of drugs){const p=imported[d.id];if(p&&Number.isFinite(p.attempts))progress[d.id]={...L.fresh(),...p,skills:{...L.fresh().skills,...p.skills}};}if(incoming.prefs&&typeof incoming.prefs==='object')Object.assign(prefs,incoming.prefs);persist();applyPrefs();$('#settings').close();render();alert('学習データを読み込みました。');}catch(err){alert('読み込みに失敗しました。JSONファイルを確認してください。');}e.target.value='';};
  document.addEventListener('error',e=>{if(!e.target.matches?.('.drug-photo'))return;const notice=document.createElement('p');notice.className='photo-empty';notice.textContent='写真を読み込めません。外観からの判断はせず、公式資料をご確認ください。';e.target.replaceWith(notice);if(session&&current()?.mode==='photo'&&!session.answered){document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);const skip=document.createElement('button');skip.className='secondary wide';skip.textContent='この問題をスキップ（記録しない）';skip.onclick=()=>{session.answered=true;next();};document.querySelector('.answers')?.after(skip);}},true);
  window.addEventListener('hashchange',render);
  applyPrefs();showStorage();render();
})();
